module system_pattern_hdmi_axi_0_2_frame_tick
   (previous_origin,
    frame_tick,
    at_origin,
    clk,
    dest_arst,
    tick0);
  output previous_origin;
  output frame_tick;
  input at_origin;
  input clk;
  input dest_arst;
  input tick0;

  wire at_origin;
  wire clk;
  wire dest_arst;
  wire frame_tick;
  wire previous_origin;
  wire tick0;

  FDPE #(
    .INIT(1'b1)) 
    previous_origin_reg
       (.C(clk),
        .CE(1'b1),
        .D(at_origin),
        .PRE(dest_arst),
        .Q(previous_origin));
  FDCE tick_reg
       (.C(clk),
        .CE(1'b1),
        .CLR(dest_arst),
        .D(tick0),
        .Q(frame_tick));
endmodule

